pub fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    // Ensure the inputs are the same length
    assert_eq!(
        condition.len(),
        arr.len(),
        "condition and arr must have equal length"
    );

    // Pre-allocate space for the results based on how many `true` flags there are
    let true_count = condition.iter().filter(|&&flag| flag).count();
    let mut result = Vec::with_capacity(true_count);

    // Zip the two vectors and push only those `arr` values whose corresponding
    // `condition` entry is `true`
    for (flag, value) in condition.into_iter().zip(arr.into_iter()) {
        if flag {
            result.push(value);
        }
    }

    result
}

